{"version":3,"sources":["powpow/rainbow-float-effect.scss","powpow/rainbow-float-effect.css"],"names":[],"mappings":"AAAA;EACI,qBAAA;EACA,iBAAA;EACA,iGAAA;EACA,0BAAA;EACA,6BAAA;EACA,oCAAA;EACA,qBAAA;EACA,uEAAA;ACCJ;;ADEA;EACI;IAAK,2BAAA;ECEP;EDDE;IAAO,6BAAA;ECIT;AACF;ADFA;EACI;;;oCAAA;EAKA;IAAW,mBAAA;ECIb;EDHE;IAAM,qBAAA;ECMR;AACF","file":"rainbow-float-effect.css","sourcesContent":[".rainbow-icon {\n    display: inline-block;\n    font-size: 1.2rem;\n    background: linear-gradient(90deg, #ff0000, #ff7700, #ffff00, #00ff00, #0000ff, #8b00ff, #ff0000);\n    background-size: 300% 100%;\n    -webkit-background-clip: text;\n    -webkit-text-fill-color: transparent;\n    background-clip: text;\n    animation: rainbowScroll 4s linear infinite, floatXY 1s linear infinite;\n}\n\n@keyframes rainbowScroll {\n    0% { background-position: 0% 50%; }\n    100% { background-position: 300% 50%; }\n}\n\n@keyframes floatXY {\n    /*0%, 100% { transform: rotate(0deg); }\n    25% { transform: rotate(-10deg);}\n    50% { transform: rotate(0deg); }\n    75% { transform: rotate(10deg); }*/\n\n    0%, 100% { transform: scale(1); }\n    50% { transform: scale(1.2); }\n\n\n}",".rainbow-icon {\n  display: inline-block;\n  font-size: 1.2rem;\n  background: linear-gradient(90deg, #ff0000, #ff7700, #ffff00, #00ff00, #0000ff, #8b00ff, #ff0000);\n  background-size: 300% 100%;\n  -webkit-background-clip: text;\n  -webkit-text-fill-color: transparent;\n  background-clip: text;\n  animation: rainbowScroll 4s linear infinite, floatXY 1s linear infinite;\n}\n\n@keyframes rainbowScroll {\n  0% {\n    background-position: 0% 50%;\n  }\n  100% {\n    background-position: 300% 50%;\n  }\n}\n@keyframes floatXY {\n  /*0%, 100% { transform: rotate(0deg); }\n  25% { transform: rotate(-10deg);}\n  50% { transform: rotate(0deg); }\n  75% { transform: rotate(10deg); }*/\n  0%, 100% {\n    transform: scale(1);\n  }\n  50% {\n    transform: scale(1.2);\n  }\n}"]}